"""Visible (partial) tests for the template engine.  Do NOT edit this file."""
import sys

from trender import render, TemplateError

failures = []


def check(name, cond):
    if not cond:
        failures.append(name)


def kind_of(text, ctx=None):
    try:
        render(text, {} if ctx is None else ctx)
    except TemplateError as e:
        return getattr(e, "kind", "?")
    except Exception as e:
        return "raised " + type(e).__name__
    return "no error"


# 1. literal text and interpolation
check("literal text", render("hello, world", {}) == "hello, world")
check("interpolation", render("Hi {{ user.name }}!", {"user": {"name": "ada"}}) == "Hi ada!")
check("integer value", render("{{ n }}", {"n": 7}) == "7")
check("missing path is empty", render("[{{ nope.deep }}]", {}) == "[]")
check("escaping", render("{{ s }}", {"s": '<a href="x">&'}) == "&lt;a href=&quot;x&quot;&gt;&amp;")

# 2. filters
check("upper/lower", render("{{ s|upper }}{{ s|lower }}", {"s": "aB"}) == "ABab")
check("len of list", render("{{ xs|len }}", {"xs": [1, 2, 3]}) == "3")
check("filter chain", render("{{ s|upper|len }}", {"s": "abc"}) == "3")
check("raw suppresses escaping", render("{{ s|raw }}", {"s": "<b>"}) == "<b>")

# 3. if / elif / else
check("if true branch", render("{% if a %}A{% else %}B{% endif %}", {"a": 1}) == "A")
check("if false branch", render("{% if a %}A{% else %}B{% endif %}", {"a": 0}) == "B")
check("elif branch", render("{% if a %}A{% elif b %}B{% else %}C{% endif %}",
                            {"a": "", "b": "yes"}) == "B")
check("if without else", render("<{% if a %}A{% endif %}>", {"a": []}) == "<>")

# 4. for loops
check("for with loop.index",
      render("{% for w in ws %}{{ loop.index }}:{{ w }};{% endfor %}", {"ws": ["a", "b"]})
      == "1:a;2:b;")
check("empty branch on empty list",
      render("{% for w in ws %}x{% empty %}none{% endfor %}", {"ws": []}) == "none")
check("no empty branch on empty list",
      render("[{% for w in ws %}x{% endfor %}]", {"ws": []}) == "[]")

# 5. whitespace control
check("strip across newlines",
      render("a\n   {%- if 1 -%}\n   b\n   {%- endif -%}\n   c", {}) == "abc")
check("strip on interpolation",
      render("x   {{- s -}}\n\n   y", {"s": "S"}) == "xSy")

# 6. loop variable scoping
ctx = {"w": "outer", "ws": ["a", "b"]}
check("loop variable restored after loop",
      render("{% for w in ws %}{{ w }}{% endfor %}[{{ w }}]", ctx) == "ab[outer]")
check("context dict unchanged", ctx == {"w": "outer", "ws": ["a", "b"]})

# 7. error kinds
check("unclosed block", kind_of("{% if 1 %}oops") == "unclosed")
check("mismatched end tag", kind_of("{% for w in ws %}{% endif %}", {"ws": []}) == "mismatch")
check("unknown filter", kind_of("{{ s|nope }}", {"s": "a"}) == "filter")

if failures:
    print("FAILED %d check(s):" % len(failures))
    for f in failures:
        print("  -", f)
    sys.exit(1)
print("ALL OK")
